def modular_sum(arr, n, m, sum):
    if (sum % m == 0):
        return True
    dp = [[False for i in range(sum + 1)] for j in range(n + 1)]
    for i in range(n + 1):
        dp[i][0] = True
    for i in range(1, n + 1):
        for j in range(1, sum + 1):
            if (arr[i - 1] <= j):
                dp[i][j] = dp[i - 1][j - arr[i - 1]] or dp[i - 1][j]
            else:
                dp[i][j] = dp[i - 1][j]
    return dp[n][sum]<|repo_name|>

